import { PerspectiveCamera, Stars, TorusKnot, useGLTF } from '@react-three/drei';
import { Canvas, useFrame } from '@react-three/fiber';
import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

// Error Boundary to handle missing model seamlessly
class ModelErrorBoundary extends React.Component<{ fallback: React.ReactNode, children: React.ReactNode }, { hasError: boolean }> {
    constructor(props: any) {
        super(props);
        this.state = { hasError: false };
    }

    static getDerivedStateFromError(error: any) {
        return { hasError: true };
    }

    componentDidCatch(error: any, errorInfo: any) {
        console.warn("Failed to load 3D model (likely missing public/deer.glb). Using fallback.", error);
    }

    render() {
        if (this.state.hasError) {
            return this.props.fallback;
        }
        return this.props.children;
    }
}

function DeerLoader() {
    // Loader that actually calls useGLTF — keep this separate so we can conditionally render
    const { scene } = useGLTF('/deer.glb', true);
    const meshRef = useRef<THREE.Group>(null!);

    useEffect(() => {
        scene.traverse((child) => {
            if ((child as THREE.Mesh).isMesh) {
                const mesh = child as THREE.Mesh;
                mesh.material = new THREE.MeshStandardMaterial({
                    color: "#ffffff",
                    wireframe: true,
                    transparent: true,
                    opacity: 0.3,
                    emissive: "#ffffff",
                    emissiveIntensity: 0.2
                });
            }
        });
    }, [scene]);

    useFrame((state, delta) => {
        // Gentle floating and rotation
        if (meshRef.current) {
            meshRef.current.rotation.y += delta * 0.1;
            meshRef.current.position.y = Math.sin(state.clock.elapsedTime * 0.5) * 0.2 - 2; // Adjust base height
        }
    });

    return <primitive object={scene} ref={meshRef} scale={0.03} position={[2, -2, 0]} rotation={[0, -Math.PI / 4, 0]} />;
}

function DeerModel() {
    // Guard: check if the asset exists before calling useGLTF to avoid parsing HTML
    const [available, setAvailable] = React.useState<boolean | null>(null);

    useEffect(() => {
        let canceled = false;

        // Prefer HEAD to avoid downloading whole file; fallback to GET if needed
        fetch('/deer.glb', { method: 'HEAD' })
            .then(res => {
                if (canceled) return;
                if (res.ok) {
                    setAvailable(true);
                } else {
                    setAvailable(false);
                }
            })
            .catch(() => {
                // Some servers don't allow HEAD — try GET
                fetch('/deer.glb')
                    .then(res2 => {
                        if (canceled) return;
                        if (res2.ok) setAvailable(true);
                        else setAvailable(false);
                    })
                    .catch(() => {
                        if (!canceled) setAvailable(false);
                    });
            });

        return () => { canceled = true; };
    }, []);

    if (available === null) {
        // Still checking — let Suspense show its fallback
        return null;
    }

    if (!available) {
        // Asset missing or inaccessible — render fallback shape instead
        return <FallbackShape />;
    }

    // Asset exists — render the real loader (which uses useGLTF)
    return <DeerLoader />;
}

function FallbackShape() {
    const meshRef = useRef<THREE.Mesh>(null!);

    useFrame((state, delta) => {
        meshRef.current.rotation.x += delta * 0.1;
        meshRef.current.rotation.y += delta * 0.15;
    });

    return (
        <TorusKnot args={[1, 0.3, 128, 16]} ref={meshRef} position={[2, 0, 0]} scale={2}>
            <meshStandardMaterial
                color="#ffffff"
                wireframe
                transparent
                opacity={0.15}
                emissive="#ffffff"
                emissiveIntensity={0.1}
            />
        </TorusKnot>
    );
}

export default function Background3D() {
    return (
        <div className="fixed top-0 left-0 w-full h-full -z-10 bg-black overflow-hidden pointer-events-none">
            <Canvas>
                <PerspectiveCamera makeDefault position={[0, 0, 10]} />
                <ambientLight intensity={0.5} />
                <pointLight position={[10, 10, 10]} intensity={1} color="#ffffff" />
                <pointLight position={[-10, -10, -10]} intensity={0.5} color="#444444" />

                <ModelErrorBoundary fallback={<FallbackShape />}>
                    <React.Suspense fallback={<FallbackShape />}>
                        <DeerModel />
                    </React.Suspense>
                </ModelErrorBoundary>

                <Stars radius={100} depth={50} count={3000} factor={4} saturation={0} fade speed={1} />
            </Canvas>
        </div>
    );
}
